// Clean-room string helpers, written from the public API descriptions.
bool str_equal(str a,str b){if a.len!=b.len{return false;}for i32 i in 0..a.len{if a.data[i]!=b.data[i]{return false;}}return true;}
str str_slice(str s,i32 a,i32 b){if a<0||b<a||b>s.len{abort();}return str{s.data+a,b-a};}
i32 str_find(str s,str needle){for i32 i=0;i<=s.len-needle.len;i++{bool match=true;for i32 j in 0..needle.len{if s.data[i+j]!=needle.data[j]{match=false;break;}}if match{return i;}}return -1;}
bool str_contains(str s,str needle){return str_find(s,needle)>=0;}
bool str_starts_with(str s,str p){if p.len>s.len{return false;}return str_equal(str_slice(s,0,p.len),p);}
bool str_ends_with(str s,str p){if p.len>s.len{return false;}return str_equal(str_slice(s,s.len-p.len,s.len),p);}
str str_trim(str s){i32 a=0;i32 b=s.len;while a<b&&(s.data[a]==' '||s.data[a]=='\n'||s.data[a]=='\t'||s.data[a]=='\r'){a++;}while b>a&&(s.data[b-1]==' '||s.data[b-1]=='\n'||s.data[b-1]=='\t'||s.data[b-1]=='\r'){b--;}return str_slice(s,a,b);}
str str_from_cstr(u8* p){if p==null{return str{null,0};}i32 n=0;while p[n]!=0{n++;}return str{p,n};}
u8* str_to_cstr(str s){u8* p=alloc<u8>(s.len+1);memcpy(p,s.data,s.len);p[s.len]=0;return p;}
string str_concat(str a,str b){string result=string(a);result.data=cast(u8*,realloc(result.data,a.len+b.len));memcpy(result.data+a.len,b.data,b.len);result.len=a.len+b.len;return result;}
struct str_buf{u8* data;i32 len;i32 cap;}
void str_buf_init(str_buf* b){b.data=null;b.len=0;b.cap=0;}
