struct TestFrameworkTime{i64 seconds,nanoseconds;}
i64 test_framework_ticks(){
    TestFrameworkTime value;
    when os(linux){test_framework_clock(1,&value);}else{test_framework_clock(6,&value);}
    return value.seconds*1000000000+value.nanoseconds;
}
string test_framework_quote(str text){
    str_buf result;str_buf_init(&result);
    str_buf_add(&result,"'");
    for i32 i in 0..text.len{
        if text.data[i]=='\''{str_buf_add(&result,"'\\''");}
        else{str_buf_add(&result,str{text.data+i,1});}
    }
    str_buf_add(&result,"'");
    string owned=string(str_buf_to_str(&result));str_buf_free(&result);return owned;
}
i32 test_framework_command(str command){
    using u8* text=str_to_cstr(command);
    i32 status=test_framework_system(text);
    if status<0{return 127;}
    if (status&127)!=0{return 128+(status&127);}
    return (status>>8)&255;
}
i32 test_framework_run(str command,i64 timeout_ms,bool* timed_out){
    *timed_out=false;
    using u8* text=str_to_cstr(command);
    i32 pid=test_framework_fork();
    if pid<0{return 127;}
    if pid==0{
        test_framework_setpgid(0,0);
        i32 status=test_framework_system(text);
        i32 code=127;
        if status>=0{if (status&127)!=0{code=128+(status&127);}else{code=(status>>8)&255;}}
        test_framework_exit(code);
        return code;
    }
    test_framework_setpgid(pid,pid);
    i64 start=test_framework_ticks();
    i32 status=0;
    while true{
        i32 waited=test_framework_waitpid(pid,&status,1);
        if waited==pid{
            if (status&127)!=0{return 128+(status&127);}
            return (status>>8)&255;
        }
        if waited<0{return 127;}
        if timeout_ms>0&&(test_framework_ticks()-start)/1000000>=timeout_ms{
            test_framework_kill(-pid,9);
            test_framework_waitpid(pid,&status,0);
            *timed_out=true;
            return 124;
        }
        test_framework_usleep(10000);
    }
    return 127;
}
