        test_framework_record(name,"fail",ms);print(",\"reason\":\"compile\"");test_framework_output(output);
    }else{print("  FAIL  {} (compile)\n{}",name,output);}
}
i32 test_run_dir(str directory){
    str filter="";i64 timeout_ms=0;
    for i32 i=1;i<get_argc();i++{
        str argument=str_from_cstr(get_arg(i));
        if str_equal(argument,"--filter")&&i+1<get_argc(){i++;filter=str_from_cstr(get_arg(i));}
        else if str_equal(argument,"--timeout")&&i+1<get_argc(){
            i++;timeout_ms=cast(i64,test_framework_strtod(get_arg(i),null)*1000);
            if timeout_ms<=0{eprint("invalid test timeout\n");return 1;}
        }else if str_equal(argument,"--changed"){eprint("test_run_dir: --changed is not implemented\n");return 1;}
    }
    using u8* key=str_to_cstr("MINC");
    str compiler=str_from_cstr(test_framework_getenv(key));
    if compiler.len==0{compiler="minc";}
    using string quoted_compiler=test_framework_quote(compiler);
    if test_framework_command("mkdir -p build/test")!=0{return 1;}
    using u8* temporary=str_to_cstr("build/test/.framework-XXXXXX");
    if test_framework_mkdtemp(temporary)==null{return 1;}
    str scratch=str_from_cstr(temporary);
    using string compile_log=format("{}/compile",scratch);
    using string run_log=format("{}/run",scratch);
    using string quoted_compile_log=test_framework_quote(compile_log);
    using string quoted_run_log=test_framework_quote(run_log);
    using string relative=format("./{}",directory);
    using string quoted_directory=test_framework_quote(str_starts_with(directory,"/")?directory:relative);
    using string list_command=format("find {} -maxdepth 1 -type f -name '*.mc' -print0 | LC_ALL=C sort -z",quoted_directory);
    using u8* list_text=str_to_cstr(list_command);
    using u8* mode=str_to_cstr("r");
    void* files=test_framework_popen(list_text,mode);
    if files==null{test_framework_rmdir(temporary);return 1;}
    TestState state=test_begin();
    str_buf path;str_buf_init(&path);
    while true{
        i32 byte=test_framework_fgetc(files);
        if byte<0{break;}
        if byte!=0{u8 value=cast(u8,byte);str_buf_add(&path,str{&value,1});continue;}
        str source=str_buf_to_str(&path);
        i32 base=0;
        for i32 j in 0..source.len{if source.data[j]=='/'{base=j+1;}}
        str name=str_slice(source,base,source.len-3);
        if str_contains(name,filter){
            using string binary=format("build/test/{}",name);
            using string quoted_source=test_framework_quote(source);
            using string quoted_binary=test_framework_quote(binary);
            using string compile=format("{} build {} -o {} >{} 2>&1",quoted_compiler,quoted_source,quoted_binary,quoted_compile_log);
            i64 start=test_framework_ticks();
