// Geometric growth preserves table indices; callers do not retain element pointers.
T* sc_table_reserve<T>(T* data,i32* capacity,i32 needed){
    if needed<0{sc_fail("table too large");}
    if needed<=*capacity{return data;}
    i32 size=*capacity;if size<16{size=16;}
    while size<needed{if size>536870911{sc_fail("table too large");}size*=2;}
    T* grown=cast(T*,realloc(data,cast(i64,size)*sizeof(T)));
    if grown==null{sc_fail("out of memory");}*capacity=size;return grown;
