void sc_reserve(ScBuffer* buffer, i32 extra) {
    if extra < 0 || buffer.len > 1073741823 - extra { sc_fail("buffer too large"); }
    i32 needed = buffer.len + extra;
    if needed <= buffer.cap { return; }
    i32 capacity = buffer.cap;
    if capacity < 64 { capacity = 64; }
    while capacity < needed { capacity *= 2; }
    u8* data = cast(u8*, realloc(buffer.data, capacity));
    if data == null { sc_fail("out of memory"); }
    buffer.data = data;
    buffer.cap = capacity;
}

