            }
            if tokens.len + 1 >= capacity {
                if capacity > 16777216 { sc_fail("too many tokens"); }
                capacity *= 2;
                tokens.data = cast(ScToken*, realloc(tokens.data, cast(i64, capacity) * sizeof(ScToken)));
                if tokens.data == null { sc_fail("out of memory"); }
            }
            tokens.data[tokens.len] = ScToken{sc_sub(source, start, index), kind, line};
            tokens.len++;
        }
        for i32 position = consumed_start; position < index; position++ {
            if source.data[position] == '\n' { line++; }
        }
    }
    tokens.data[tokens.len] = ScToken{"", 0, line};
    tokens.len++;
    return tokens;
}

// Open-addressed lookup only: source-order arrays remain the emission authority.
struct ScIndexEntry {str key;i32 scope;i32 value;}
struct ScIndex {ScIndexEntry* entries;i32 capacity;i32 count;}
u32 sc_index_hash(str key,i32 scope){
    u32 hash=2166136261;
    for i32 i=0;i<key.len;i++{hash=(hash^cast(u32,key.data[i]))*16777619;}
    return (hash^cast(u32,scope))*16777619;
}
i32 sc_index_slot(ScIndex* index,str key,i32 scope){
    i32 slot=cast(i32,sc_index_hash(key,scope)&cast(u32,index.capacity-1));
    while index.entries[slot].value!=0{
        if index.entries[slot].scope==scope&&sc_equal(index.entries[slot].key,key){break;}
        slot=(slot+1)&(index.capacity-1);
    }
    return slot;
}
i32 sc_index_get(ScIndex* index,str key,i32 scope){
    if index.capacity==0{return -1;}
    return index.entries[sc_index_slot(index,key,scope)].value-1;
}
void sc_index_put(ScIndex* index,str key,i32 scope,i32 value){
    if index.capacity==0||index.count>=index.capacity/2{
        i32 capacity=index.capacity;
        if capacity>536870911{sc_fail("index too large");}
        i32 size=capacity==0?16:capacity*2;
        ScIndexEntry* old=index.entries;
        index.entries=alloc<ScIndexEntry>(size);if index.entries==null{sc_fail("out of memory");}
        index.capacity=size;
        for i32 i=0;i<size;i++{index.entries[i].value=0;}
        for i32 i=0;i<capacity;i++{if old[i].value!=0{index.entries[sc_index_slot(index,old[i].key,old[i].scope)]=old[i];}}
        free(old);
    }
    i32 slot=sc_index_slot(index,key,scope);
    if index.entries[slot].value==0{index.count++;}
    index.entries[slot]=ScIndexEntry{key,scope,value+1};
}
void sc_index_clear(ScIndex* index){free(index.entries);index.entries=null;index.capacity=0;index.count=0;}

examples.source:
i32 main() {
    print("Hello, world! 🎉\n");
    return 0;
}

// Floats print with up to six decimals, trailing zeros trimmed; huge and tiny values switch to scientific form.
i32 main() {
    f64 third = 1.0 / 3.0;
    f32 ratio = 2.5f;
    print("{} {} {}\n", third, ratio, 100.0);
    print("{} {}\n", 1.0e20, 0.0000001);
    f64 zero = 0.0;
    print("{} {} {}\n", 1.0 / zero, -1.0 / zero, zero / zero);
    return 0;
}

// Integers widen to f64 on their own; going back needs cast(), which truncates toward zero and saturates.
i32 main() {
    i32 cents = 1999;
    f64 dollars = cents;
    dollars = dollars / 100.0;
    print("{} cents = {} dollars\n", cents, dollars);
    f64 up = 7.9;
    f64 down = -7.9;
    print("cast(i32, {}) = {}, cast(i32, {}) = {}\n", up, cast(i32, up), down, cast(i32, down));
    f64 huge = 1.0e20;
    f64 nothing = 0.0 / 0.0;
    print("{} saturates to {}, nan becomes {}\n", huge, cast(i32, huge), cast(i32, nothing));
    u64 big = 9007199254740993;
    print("{} rounds to {} as an f64\n", big, cast(u64, cast(f64, big)));
    return 0;
}

// Floats inside structs, arrays and vectors print just like plain floats.
struct Reading {
    f32 celsius;
    f64 pressure;
}

i32 main() {
    Reading today = Reading{21.5f, 1013.25};
    f32[3] samples = {0.1f, 100f, 1e20f};
    print("{} {}\n", today.celsius, today.pressure);
    print("{} {} {}\n", samples[0], samples[1], samples[2]);

    float4 v = float4{1f, 2.5f, -3.125f, 1e-7f};
    float2 swapped = v.yx;
    print("{} {} {} {}\n", v.x, v.y, v.z, v.w);
    print("{} {}\n", swapped.x, swapped.y);
    return 0;
}

i32 main() {
    // Each harness run owns its working directory and this relative fixture file.
    u8[16] path = {'n','a','t','i','v','e','_','f','i','l','e','.','t','m','p',0};
    u8[4] content = {65, 0, 67, 68};
    u8[8] received;
    i64 handle = open(&path[0], 1);
    if handle < 0 { return 10; }
    i32 written = write(handle, &content[0], 4);
    close(handle);
    handle = open(&path[0], 0);
    if handle < 0 { return 11; }
    i32 count = read(handle, &received[0], 8);
    close(handle);
    print("{} {} {} {} {} {}\n", written, count,
          received[0], received[1], received[2], received[3]);

    content[0] = 90;
    handle = open(&path[0], 1);
    if handle < 0 { return 12; }
    written = write(handle, &content[0], 1);
    close(handle);
    handle = open(&path[0], 0);
    if handle < 0 { return 13; }
    count = read(handle, &received[0], 8);
    close(handle);
    print("{} {} {}\n", written, count, received[0]);
    return 0;
}

// Structs, designated initializers and pointers to structs.
struct Vec2 { i32 x, y; }
struct Body { Vec2 pos; Vec2 vel; }

void step(Body* b) {
    b.pos.x += b.vel.x;
    b.pos.y += b.vel.y;
}

i32 main() {
    Body ball = Body{.pos = Vec2{0, 10}, .vel = Vec2{.x = 3, .y = -2}};
    for i32 t = 1; t <= 4; t++ {
        step(&ball);
        print("t={} ball at ({}, {})\n", t, ball.pos.x, ball.pos.y);
    }
    return 0;
}

// Tagged unions: each case carries its own data, and switch unpacks it.
union Shape { Circle(i32), Rect(i32, i32), Dot }

i32 main() {
    Shape a = Circle(2);
    switch a {
        case Circle(r): { print("circle r={} area {}\n", r, 3 * r * r); }
        case Rect(w, h): { print("rect {}x{} area {}\n", w, h, w * h); }
        case Dot: { print("dot\n"); }
    }
    Shape b = Rect(3, 4);
    switch b {
        case Circle(r): { print("circle r={} area {}\n", r, 3 * r * r); }
        case Rect(w, h): { print("rect {}x{} area {}\n", w, h, w * h); }
        case Dot: { print("dot\n"); }
    }
    return 0;
}

// Generic tagged unions: one Option<T> declaration, a separate type for each T.
union Option<T> { Some(T), None }

struct Point { i32 x; i32 y; }

i32 value_or(Option<i32> value, i32 fallback) {
    switch value {
        case Some(n): {
            return n;
        }
        case None: {
            return fallback;
        }
    }
    return fallback;
}

i32[4] items = {10, 20, 30, 40};

Option<i32> find(i32 wanted) {
    for i32 i = 0; i < 4; i++ {
        if items[i] == wanted {
            return Some(i);
        }
    }
    return None;
}

i32 main() {
    print("index of 30: {}\n", value_or(find(30), -1));
    print("index of 99: {}\n", value_or(find(99), -1));

    Option<Point> corner = Some({3, 4});
    switch corner {
        case Some(p): {
            print("point: {}, {}\n", p.x, p.y);
        }
        case None: {
            print("no point\n");
        }
    }
    return 0;
}

// Generic functions with constraints: one definition, many integer types.
T largest<T: Integer>(T a, T b) {
    if a > b { return a; }
    return b;
}

T sum_to<T: Signed>(T n) {
    if n == 0 { return 0; }
    return n + sum_to<T>(n - 1);
}

i32 main() {
    print("{} {}\n", largest<i32>(7, 42), largest<u8>(200, 100));
    print("{} {}\n", sum_to<i32>(10), sum_to<i64>(100));
    return 0;
}

// Functions are values: store them in variables and pass them around.
i32 square(i32 x) { return x * x; }
i32 negate(i32 x) { return -x; }

void apply_all(fn(i32):i32 f, i32* xs, i32 n) {
    for i32 i = 0; i < n; i++ { xs[i] = f(xs[i]); }
}

i32 main() {
    i32[4] xs = {1, 2, 3, 4};
    apply_all(square, &xs[0], 4);
    apply_all(negate, &xs[0], 4);
    print("{} {} {} {}\n", xs[0], xs[1], xs[2], xs[3]);
    fn(i32):i32 chosen = square;
    print("{}\n", chosen(12));
    return 0;
}

// Pass whole structs through a function pointer, even as a { } literal.
struct Point { i32 x; i32 y; }

i32 manhattan(Point p) {
    return p.x + p.y;
}
i32 area(Point p) {
    return p.x * p.y;
}

struct Measure { fn(Point): i32 run; }

i32 main() {
    Measure[2] tools = {{&manhattan}, {&area}};
    Point p = {3, 4};
    for i32 i in 0..2 {
        print("{} {}\n", tools[i].run(p), tools[i].run({.y = 10, .x = 2}));
    }
    return 0;
}

// Arrays and slices: a slice is a view (pointer + length) into an array.
i32 main() {
    i32[6] values = {1, 2, 3, 4, 5, 6};
    []i32 middle = values[1..5];
    i32 sum = 0;
    for i32 i = 0; i < middle.len; i++ { sum += middle[i]; }
    print("middle has {} items, sum {}\n", middle.len, sum);
    middle[0] = 100;
    print("writing through the slice changes the array: {}\n", values[1]);
    return 0;
}

// Vectors: four lanes at once, with swizzles to shuffle them.
i32 main() {
    int4 a = int4{1, 2, 3, 4};
    int4 b = a * 10 + int4{5}; // every lane, one operator
    print("{} {} {} {}\n", b.x, b.y, b.z, b.w);

    int2 pair = b.wx; // pick lanes by name
    print("{} {}\n", pair.x, pair.y);

    a.xy = a.yx; // swap two lanes
    a.w += 100; // one lane on its own
    int4 shifted = (a << 2) | 1;
    print("{} {} {} {}\n", a.x, a.y, a.z, a.w);
    print("{} {}\n", shifted.x, shifted.w);

    uint4 big = uint4{4294967295}; // lanes wrap like u32
    uint4 wrapped = big + uint4{2};
    print("{} {}\n", wrapped.x, (big >> 28).y);
    return 0;
}

// SIMD bytes: look at sixteen bytes at once, and add up their products.
i32 main() {
    i8[16] data;
    i8[16] twos;
    for i32 i in 0..16 {
        data[i] = cast(i8, (i * 5) % 4); // 0 1 2 3 0 1 2 3 ...
        twos[i] = 2;
    }
    i8x16 bytes = i8x16_load(&data[0]);
    i8x16 same = i8x16_eq(bytes, i8x16_load(&twos[0])); // 255 where equal, else 0
    i32 mask = i8x16_movemask(same); // one bit per byte
    i32 count = 0;
    for i32 bit in 0..16 {
        if ((mask >> bit) & 1) == 1 {
            count++;
        }
    }
    print("mask {} -> {} bytes equal 2\n", mask, count);

    int4 acc;
    acc = dot_acc_i8(acc, bytes, bytes); // four sums of four products
    print("sum of squares {}\n", sum4(acc));

    i8x16 shifted = byte_shl(bytes, 4); // move four bytes up, zero fill
    i8[16] out;
    i8x16_store(&out[0], shifted);
    print("{} {} {} {} {}\n", out[0], out[3], out[4], out[5], out[15]);
    return 0;
}

// String views and formatting.
str middle(str text) { return str{text.data + 1, text.len - 2}; }

i32 main() {
    str word = "[minc]";
    str inner = middle(word);
    str line = format("{} has {} letters, {} > {} is {}", inner, inner.len, 3, 2, 3 > 2);
    print("{}\n", line);
    return 0;
}

// Manual memory: alloc and free. Every allocation must be freed exactly once.
i32 main() {
    i32* squares = alloc<i32>(5);
    for i32 i = 0; i < 5; i++ { squares[i] = i * i; }
    i32 sum = 0;
    for i32 i = 0; i < 5; i++ { sum += squares[i]; }
    print("squares {} {} {}, sum {}\n", squares[1], squares[2], squares[4], sum);
    free(squares);
    return 0;
}

// defer runs a cleanup when the scope ends, last one first, even on early exits.
i32 find_first(i32* xs, i32 n, i32 wanted) {
    defer print("  searched for {}\n", wanted);
    for i32 i = 0; i < n; i++ {
        defer print("  checked slot {}\n", i);
        if xs[i] == wanted {
            return i;
        }
    }
    return -1;
}

i32 main() {
    i32[4] xs = {7, 3, 9, 5};
    {
        defer print("goodbye\n");
        defer print("hello\n");
    }
    print("found at {}\n", find_first(&xs[0], 4, 9));
    print("found at {}\n", find_first(&xs[0], 4, 8));
    return 0;
}

// using frees a value when its block ends; move hands it to someone else instead.
string greeting(str name) {
    using string text = format("hello, {}", name);
    if name.len == 0 {
        return string("hello, nobody"); // text is freed on the way out
    }
    return move(text); // text goes to the caller, nothing is freed
}

i32 main() {
    using string a = greeting("minc");
    using string b = greeting("");
    print("{}\n{}\n", a, b);
    for i32 i in 0..2 {
        using u8* scratch = alloc<u8>(16); // freed at the end of every pass
        scratch[0] = cast(u8, 65 + i);
        print("pass {}: {}\n", i, scratch[0]);
    }
    return 0;
}

// See how byte escapes and a Unicode escape become UTF-8 bytes.
i32 main() {
    str sample = "\xFF\0\u{E9}";
    print("{} {} {} {} {}\n", sample.len, sample.data[0], sample.data[1], sample.data[2], sample.data[3]);
    return 0;
}

// Forward declarations: types can be used before they are defined, and constants can size arrays.
struct Pond;
struct Frog { Pond* home; i32 jumps; }
struct Pond { Frog[SEATS] seats; i32 count; }
const i32 SEATS = 3;

void sit(Pond* pond, i32 jumps) {
    Frog f = Frog{pond, jumps};
    pond.seats[pond.count] = f;
    pond.count++;
}

i32 main() {
    Pond pond;
    for i32 i = 0; i < SEATS; i++ {
        sit(&pond, (i + 1) * 4);
    }
    i32 total = 0;
    for i32 i = 0; i < pond.count; i++ {
        Frog f = pond.seats[i];
        print("seat {} jumps {} same pond {}\n", i, f.jumps, f.home == &pond);
        total += f.jumps;
    }
    print("{} frogs, {} jumps\n", pond.count, total);
    return 0;
}

// Bit tricks and raw memory: popcount, clz, ctz, bswap, mulhi, memset and memcpy are built in.
i32 main() {
    u32 n = 0x12345678;
    print("popcount {} clz {} ctz {}\n", popcount(n), clz(n), ctz(n));
    print("bswap {} = {}\n", n, bswap(n));
    u64 big = 18446744073709551615;
    print("high half of big*big: {}\n", mulhi(big, big));
    u8[8] a;
    u8[8] b;
    memset(&a[0], 7, 8);
    memcpy(&b[0], &a[0], 8);
    print("copied {} {}\n", b[0], b[7]);
    return 0;
}

// @must_use asks callers to look at a result; `ignore` says "I know, drop it on purpose".
i32 attempts = 0;

@must_use i32 try_connect(i32 port) {
    attempts = attempts + 1;
    print("trying port {}\n", port);
    return port % 2;
}

i32 main() {
    ignore try_connect(8080);
    i32 ok = try_connect(8081);
    ignore try_connect(ok);
    print("{} attempts, last result {}\n", attempts, ok);
    return 0;
}

// Replace the allocator: the program sees every alloc, realloc and free (this one always says no).
i32 asked = 0;
i32 resized = 0;
i32 released = 0;
i64 biggest = 0;

void* __minc_alloc(i64 n) {
    asked++;
    if n > biggest {
        biggest = n;
    }
    return null;
}
void __minc_free(void* p) {
    released++;
}
void* __minc_realloc(void* p, i64 n) {
    resized++;
    return null;
}

i32 main() {
    i32* numbers = alloc<i32>(10);
    if numbers == null {
        print("no memory for 10 numbers\n");
    }
    void* more = realloc(numbers, 4096);
    if more == null {
        print("no memory to grow either\n");
    }
    free(more);
    print("alloc {}, realloc {}, free {}, largest request {} bytes\n", asked, resized, released, biggest);
    return 0;
}

// FizzBuzz with a range loop and an integer switch: grouped cases, default, fallthrough.
i32 kind(i32 n) {
    switch n % 15 {
        case 0: {
            return 3;
        }
        case 3, 6, 9, 12: {
            return 1;
        }
        case 5, 10: {
            return 2;
        }
        default: {
            return 0;
        }
    }
}

i32 main() {
    for i32 i in 1..16 {
        switch kind(i) {
            case 1: {
                print("Fizz ");
            }
            case 2: {
                print("Buzz ");
            }
            case 3: {
                print("FizzBuzz ");
            }
            default: {
                print("{} ", i);
            }
        }
    }
    print("\n");
    // fallthrough also runs the next case's body
    for i32 level in 0..3 {
        print("level {}:", level);
        switch level {
            case 0: {
                print(" boot");
                fallthrough;
            }
            case 1: {
                print(" load");
                fallthrough;
            }
            default: {
                print(" run");
            }
        }
        print("\n");
    }
    return 0;
}

// Enums are distinct i32 types: members count up, and cast() converts between them.
enum Color { RED, GREEN = 4, BLUE }
enum Shape { DOT, LINE = 7 }
Color next(Color c) {
    if c == RED {
        return GREEN;
    }
    return BLUE;
}
i32 main() {
    Color c = next(RED);
    Shape s = LINE;
    print("{} {} {}\n", c, next(c), s);
    print("{} {}\n", cast(i32, c) + cast(i32, s), sizeof(Color));
    return 0;
}

// Filling slices: write several elements at once with a brace list.
i32[8] shelf;
i32 main() {
    shelf[0..3] = {10, 20, 30};
    shelf[5..] = {60, 70, 80};
    []i32 top = shelf[5..8];
    top[1..] = {99, 98};
    for i32 i in 0..8 {
        print("{} ", shelf[i]);
    }
    print("\n");
    print("the top has {} items, the first is {}\n", top.len, top[0]);
    return 0;
}

// The compiler tracks ownership: this program is rejected at compile time.
// Try deleting the print after free, then run again.
i32 main() {
    string s = string("short-lived");
    free(s);
    print("{}\n", s);
    return 0;
}

