// Whitespace-only formatter; the shared parser is the syntax authority.
import "../selfhost/parser.mc";
const i32 FMT_INDENT = 4;
struct FmtToken {
    str text;
    i32 line, end_line;
    bool comment, own_line;
    i32 lexical, role, mate, brace, parent;
    bool expand;
}
struct FmtTokens {
    FmtToken* data;
    i32 len, cap;
}
void fmt_push(FmtTokens* items, FmtToken token) {
    items.data = sc_table_reserve<FmtToken>(items.data, &items.cap, items.len + 1);
    items.data[items.len] = token;
    items.len++;
}
bool fmt_utf8(str source) {
    i32 i = 0;
    while i < source.len {
        u8 lead = source.data[i];
        if lead < 128 {
            i++;
            continue;
        }
        i32 count = 0;
        i32 point = 0;
        i32 minimum = 0;
        if lead >= 194 && lead <= 223 {
            count = 2;
            point = cast(i32, lead & 31);
            minimum = 128;
        } else if lead >= 224 && lead <= 239 {
            count = 3;
            point = cast(i32, lead & 15);
            minimum = 2048;
        } else if lead >= 240 && lead <= 244 {
            count = 4;
            point = cast(i32, lead & 7);
            minimum = 65536;
        } else {
            return false;
        }
        if count > source.len - i {
            return false;
        }
        for i32 j = 1; j < count; j++ {
            u8 next = source.data[i + j];
            if next < 128 || next > 191 {
                return false;
            }
            point = point * 64 + cast(i32, next & 63);
        }
        if point < minimum || point > 1114111 || (point >= 55296 && point <= 57343) {
            return false;
        }
        i += count;
    }
    return true;
}
// Take raw spellings from the lexer, interleaving the comments it skips.
FmtTokens fmt_tokens(str source, AstTokens lexical) {
    FmtTokens result;
    i32 i = 0;
    i32 line = 1;
    i32 token = 0;
    bool own = true;
    while i + 3 <= source.len && source.data[i] == 239 && source.data[i + 1] == 187 && source.data[i + 2] == 191 {
        i += 3;
    }
    while i < source.len {
        if ast_lex_space(source.data[i]) {
            if source.data[i] == '\n' {
                line++;
                own = true;
            }
            i++;
            continue;
        }
        i32 start = i;
        i32 first_line = line;
        bool starts_line = own;
        bool comment = false;
        if ast_lex_starts(source, i, "//") {
            comment = true;
            while i < source.len && source.data[i] != '\n' {
                i++;
            }
        } else if ast_lex_starts(source, i, "/*") {
            comment = true;
            i += 2;
            while i < source.len && !ast_lex_starts(source, i, "*/") {
                i++;
            }
            i += 2;
        } else {
            i += lexical.data[token].text.len;
            token++;
        }
        for i32 j = start; j < i; j++ {
            if source.data[j] == '\n' {
                line++;
            }
        }
        fmt_push(&result, FmtToken{
            sc_sub(source, start, i), first_line, line, comment, starts_line, comment ? -1 : token - 1, 0, -1, 0, -1, false
        });
        own = false;
    }
    return result;
}
void fmt_newline(ScBuffer* out) {
    if out.len > 0 && out.data[out.len - 1] != '\n' {
        sc_byte(out, '\n');
    }
}
void fmt_indent(ScBuffer* out, i32 depth) {
    if out.len == 0 || out.data[out.len - 1] == '\n' {
        for i32 n = 0; n < depth * FMT_INDENT; n++ {
            sc_byte(out, ' ');
        }
    }
}
void fmt_space(ScBuffer* out) {
    if out.len > 0 && out.data[out.len - 1] != '\n' && out.data[out.len - 1] != ' ' {
        sc_byte(out, ' ');
    }
}
bool fmt_is(str text, str expected) {
    return sc_equal(text, expected);
}
bool fmt_word(u8 c) {
    return sc_alpha(c) || sc_digit(c) || c >= 128;
}
