}
i32 main() {
    if get_argc() > 2 {
        eprint("usage: fmt [source.mc]\n");
        return 1;
    }
    str filename = "<stdin>";
    str source;
    if get_argc() == 2 {
        filename = fmt_from_cstr(get_arg(1));
        source = sc_read(filename);
    } else {
        i64 stdin_handle = 0;
        ScBuffer input;
        while true {
            sc_reserve(&input, 4096);
            i32 count = read(stdin_handle, input.data + input.len, 4096);
            if count < 0 {
                eprint("fmt: cannot read stdin\n");
                return 1;
            }
            if count == 0 {
                break;
            }
            input.len += count;
        }
        source = sc_text(&input);
    }
    if !fmt_utf8(source) {
        eprint("fmt: stream did not contain valid UTF-8\n");
        return 1;
    }
    AstParseResult parsed = ast_parse(source, filename);
    if parsed.error.len > 0 {
        eprint("fmt: {}\n", parsed.error);
        return 1;
    }
    AstLexResult lexical = ast_lex(source);
    FmtTokens tokens = fmt_tokens(source, lexical.tokens);
    fmt_classify(tokens, lexical.tokens);
    str output = fmt_render(tokens);
    print("{}", output);
    return 0;
}
